com.mirth.connect.plugins.javascriptstep.script:
// script 1: route by message type
var type = msg['MSH']['MSH.9']['MSH.9.1'].toString();
var routes = { 'ADT': 'adt', 'ORM': "orders", 'ORU': 'results' };
channelMap.put('route', routes[type] || 'unknown');

// script 2
function formatName(last, first) {
    return last + ', ' + first + ' <' + "x&y" + '>';
}
logger.info(formatName('DOE', 'JANE'));

// script 3 (leading whitespace kept)
var total = 0;
for (var i = 0; i < 3; i++) { total += i; }
globalMap.put('lastTotal', total);

// script 4
var pid = msg['PID']['PID.3']['PID.3.1'].toString();
if (pid.length > 0 && pid.indexOf('-') < 0) {
	channelMap.put('patientId', pid);
}
return;

