/**
	Synthetic code template formatName.

	@param {String} value - input
	@return {String} result
*/
function formatName(value) {
	if (value == null) { return ''; }
	return String(value).replace(/\s+/g, ' ') + (value.length > 3 && value !== "n/a" ? '' : '!');
}

